parameters.jsCode:
const data = $json;

const requiredFields = [
  "Reporter Name",
  "Reporter Email",
  "Bug Title",
  "Bug Description",
  "Steps to Reproduce",
  "Expected Behavior",
  "Actual Behavior",
  "Environment",
  "Application Version"
];

const missingFields = requiredFields.filter(
  field =>
    data[field] === undefined ||
    data[field] === null ||
    data[field] === ""
);

return {
  json: {
    ...data,
    data_valid: missingFields.length === 0,
    missing_fields: missingFields
  }
};

